# TCS Coding - most asked
QUESTIONS.extend([
    make_question("tcs-c001","tcs","coding","Write a program to reverse a string in Python.","def reverse_string(s):\n    return s[::-1]","Python slicing with step -1 reverses the string","Strings","easy",test_cases=[{"input":"s='hello'","output":"'olleh'","hidden":False},{"input":"s='world'","output":"'dlrow'","hidden":True}],examples=[{"input":"s = 'hello'","output":"'olleh'","explanation":"String reversed character by character"}],provenance="https://prepinsta.com/tcs-nqt/placement-papers/"),
    make_question("tcs-c002","tcs","coding","Write a program to find the factorial of a number.","def factorial(n):\n    return 1 if n == 0 else n * factorial(n-1)","Base case: factorial(0) = 1. Recursive case: n! = n × (n-1)!","Recursion","easy",test_cases=[{"input":"n=5","output":"120","hidden":False},{"input":"n=0","output":"1","hidden":True}],examples=[{"input":"n = 5","output":"120","explanation":"5! = 5×4×3×2×1 = 120"}],provenance="https://prepinsta.com/tcs-nqt/placement-papers/"),
    make_question("tcs-c003","tcs","coding","Write a program to check if a number is prime.","def is_prime(n):\n    if n < 2: return False\n    for i in range(2, int(n**0.5)+1):\n        if n % i == 0: return False\n    return True","Check divisibility from 2 to sqrt(n)","Number Theory","medium",test_cases=[{"input":"n=17","output":"True","hidden":False},{"input":"n=4","output":"False","hidden":True}],examples=[{"input":"n = 17","output":"True","explanation":"17 has no divisors other than 1 and 17"}],provenance="https://prepinsta.com/tcs-nqt/placement-papers/"),
    make_question("tcs-c004","tcs","coding","Write a program to find the Fibonacci series up to n terms.","def fibonacci(n):\n    a, b = 0, 1\n    result = []\n    for _ in range(n):\n        result.append(a)\n        a, b = b, a + b\n    return result","Start with 0, 1. Each next term is sum of previous two","Series","easy",test_cases=[{"input":"n=5","output":"[0,1,1,2,3]","hidden":False},{"input":"n=8","output":"[0,1,1,2,3,5,8,13]","hidden":True}],examples=[{"input":"n = 5","output":"[0,1,1,2,3]","explanation":"First 5 Fibonacci numbers"}],provenance="https://prepinsta.com/tcs-nqt/placement-papers/"),
    make_question("tcs-c005","tcs","coding","Write a program to check if a string is a palindrome.","def is_palindrome(s):\n    s = s.lower().replace(' ', '')\n    return s == s[::-1]","Remove spaces, convert to lowercase, compare with reverse","Strings","easy",test_cases=[{"input":"s='madam'","output":"True","hidden":False},{"input":"s='hello'","output":"False","hidden":True}],examples=[{"input":"s = 'madam'","output":"True","explanation":"madam reads same forwards and backwards"}],provenance="https://prepinsta.com/tcs-nqt/placement-papers/"),
    make_question("tcs-c006","tcs","coding","Write a program to find the sum of digits of a number.","def sum_of_digits(n):\n    return sum(int(d) for d in str(n))","Convert to string, iterate digits, sum them","Numbers","easy",test_cases=[{"input":"n=12345","output":"15","hidden":False},{"input":"n=999","output":"27","hidden":True}],examples=[{"input":"n = 12345","output":"15","explanation":"1+2+3+4+5 = 15"}],provenance="https://prepinsta.com/tcs-nqt/placement-papers/"),
    make_question("tcs-c007","tcs","coding","Write a program to find the largest element in an array.","def find_max(arr):\n    if not arr: return None\n    max_val = arr[0]\n    for num in arr[1:]:\n        if num > max_val:\n            max_val = num\n    return max_val","Initialize max with first element, compare with rest","Arrays","easy",test_cases=[{"input":"arr=[3,1,4,1,5,9]","output":"9","hidden":False},{"input":"arr=[-5,-2,-8]","output":"-2","hidden":True}],examples=[{"input":"arr = [3,1,4,1,5,9]","output":"9","explanation":"9 is the largest element"}],provenance="https://prepinsta.com/tcs-nqt/placement-papers/"),
    make_question("tcs-c008","tcs","coding","Write a program to count vowels in a string.","def count_vowels(s):\n    vowels = set('aeiouAEIOU')\n    return sum(1 for ch in s if ch in vowels)","Use a set of vowels and count matching characters","Strings","easy",test_cases=[{"input":"s='hello'","output":"2","hidden":False},{"input":"s='aeiou'","output":"5","hidden":True}],examples=[{"input":"s = 'hello'","output":"2","explanation":"'e' and 'o' are vowels"}],provenance="https://prepinsta.com/tcs-nqt/placement-papers/"),
    make_question("tcs-c009","tcs","coding","Write a program to remove duplicates from a sorted array.","def remove_duplicates(arr):\n    if not arr: return 0\n    i = 0\n    for j in range(1, len(arr)):\n        if arr[j] != arr[i]:\n            i += 1\n            arr[i] = arr[j]\n    return i + 1","Two pointers: i tracks unique position, j scans ahead","Arrays","medium",test_cases=[{"input":"arr=[1,1,2,2,3,3]","output":"3","hidden":False},{"input":"arr=[0,0,1,1,1,2,2,3,3,4]","output":"5","hidden":True}],examples=[{"input":"arr = [1,1,2,2,3,3]","output":"3","explanation":"After removing duplicates: [1,2,3]"}],provenance="https://prepinsta.com/tcs-nqt/placement-papers/"),
    make_question("tcs-c010","tcs","coding","Write a program to find the GCD of two numbers.","import math\ndef gcd(a, b):\n    return math.gcd(a, b)","Use Euclidean algorithm","Number Theory","easy",test_cases=[{"input":"a=12, b=18","output":"6","hidden":False},{"input":"a=100, b=85","output":"5","hidden":True}],examples=[{"input":"a = 12, b = 18","output":"6","explanation":"GCD of 12 and 18 is 6"}],provenance="https://prepinsta.com/tcs-nqt/placement-papers/"),
])

